PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS businesses(id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, nit TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', receipt_width INTEGER NOT NULL DEFAULT 80);
INSERT OR IGNORE INTO businesses(id,name,kind) VALUES(1,'Mini market','market'),(2,'Ferretería','hardware');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','cashier')), businesses TEXT NOT NULL DEFAULT '[1,2]', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sku TEXT NOT NULL, barcode TEXT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL CHECK(unit IN ('und','g','m')), price INTEGER NOT NULL CHECK(price>=0), min_stock INTEGER NOT NULL DEFAULT 0, perishable INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE(business_id,sku), UNIQUE(business_id,barcode));
CREATE INDEX IF NOT EXISTS idx_products_business ON products(business_id,active);
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), product_id INTEGER NOT NULL REFERENCES products(id), code TEXT NOT NULL, expires TEXT, qty INTEGER NOT NULL CHECK(qty>=0), cost INTEGER NOT NULL CHECK(cost>=0), supplier TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_lots_product ON lots(business_id,product_id,expires);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, document TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', credit_limit INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_customers_business ON customers(business_id);
CREATE TABLE IF NOT EXISTS cash_sessions(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), user_id INTEGER NOT NULL REFERENCES users(id), opened TEXT NOT NULL, opening INTEGER NOT NULL CHECK(opening>=0), closed TEXT, counted INTEGER, expected INTEGER, note TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_open_cash ON cash_sessions(business_id) WHERE closed IS NULL;
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER REFERENCES customers(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, valid_until TEXT NOT NULL, lines TEXT NOT NULL, total INTEGER NOT NULL, converted_sale INTEGER, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), number INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), customer_id INTEGER REFERENCES customers(id), created TEXT NOT NULL, total INTEGER NOT NULL, cost INTEGER NOT NULL, debt INTEGER NOT NULL DEFAULT 0, original_debt INTEGER NOT NULL DEFAULT 0, due TEXT, status TEXT NOT NULL DEFAULT 'active', void_reason TEXT, request_id TEXT NOT NULL, quote_id INTEGER REFERENCES quotes(id), cash_received INTEGER NOT NULL DEFAULT 0, change_given INTEGER NOT NULL DEFAULT 0, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE INDEX IF NOT EXISTS idx_sales_business_date ON sales(business_id,created);
CREATE TABLE IF NOT EXISTS sale_lines(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL, unit TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), price INTEGER NOT NULL, total INTEGER NOT NULL, cost INTEGER NOT NULL, allocations TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS unregistered_sale_lines(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), description TEXT NOT NULL, qty INTEGER NOT NULL, unit TEXT NOT NULL DEFAULT 'und', price INTEGER NOT NULL, discount INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_unregistered_sale_lines_sale ON unregistered_sale_lines(sale_id);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sale_id INTEGER REFERENCES sales(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, method TEXT NOT NULL, amount INTEGER NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_payments_cash ON payments(cash_id);
CREATE TABLE IF NOT EXISTS cash_moves(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, amount INTEGER NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_moves(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), product_id INTEGER NOT NULL REFERENCES products(id), lot_id INTEGER NOT NULL REFERENCES lots(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, qty INTEGER NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_stock_moves_business ON stock_moves(business_id,created);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, business_id INTEGER REFERENCES businesses(id), user_id INTEGER REFERENCES users(id), created TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_queue(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sale_id INTEGER NOT NULL REFERENCES sales(id), recipient TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS receivables(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER NOT NULL REFERENCES customers(id), sale_id INTEGER NOT NULL UNIQUE REFERENCES sales(id), created TEXT NOT NULL, original_amount INTEGER NOT NULL, paid_amount INTEGER NOT NULL DEFAULT 0, returned_amount INTEGER NOT NULL DEFAULT 0, balance INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('Pendiente','Parcialmente pagado','Pagado','Anulado')));
CREATE INDEX IF NOT EXISTS idx_receivables_customer ON receivables(business_id,customer_id,status);
CREATE TABLE IF NOT EXISTS receivable_moves(id INTEGER PRIMARY KEY, receivable_id INTEGER NOT NULL REFERENCES receivables(id), business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER NOT NULL REFERENCES customers(id), sale_id INTEGER NOT NULL REFERENCES sales(id), payment_id INTEGER REFERENCES payments(id), created TEXT NOT NULL, kind TEXT NOT NULL, amount INTEGER NOT NULL, balance_after INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), note TEXT NOT NULL DEFAULT '', request_id TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS idx_receivable_moves_customer ON receivable_moves(business_id,customer_id,created);
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), number INTEGER NOT NULL, supplier TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Activa', note TEXT NOT NULL DEFAULT '', request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS purchase_lines(id INTEGER PRIMARY KEY, purchase_id INTEGER NOT NULL REFERENCES purchases(id), product_id INTEGER NOT NULL REFERENCES products(id), lot_id INTEGER NOT NULL REFERENCES lots(id), qty INTEGER NOT NULL, returned_qty INTEGER NOT NULL DEFAULT 0, cost INTEGER NOT NULL, cost_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_returns(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), number INTEGER NOT NULL, purchase_id INTEGER REFERENCES purchases(id), supplier TEXT NOT NULL, created TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Registrada', manual INTEGER NOT NULL DEFAULT 0, request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS purchase_return_lines(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL REFERENCES purchase_returns(id), purchase_line_id INTEGER REFERENCES purchase_lines(id), product_id INTEGER NOT NULL REFERENCES products(id), lot_id INTEGER REFERENCES lots(id), qty INTEGER NOT NULL, cost INTEGER NOT NULL, cost_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_returns(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), number INTEGER NOT NULL, sale_id INTEGER REFERENCES sales(id), customer_id INTEGER REFERENCES customers(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), created TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', refund_method TEXT NOT NULL, total INTEGER NOT NULL, debt_reduction INTEGER NOT NULL DEFAULT 0, stock_return INTEGER NOT NULL DEFAULT 1, request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS sales_return_lines(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL REFERENCES sales_returns(id), sale_line_id INTEGER REFERENCES sale_lines(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, price INTEGER NOT NULL, price_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL, cost INTEGER NOT NULL, restock INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS document_emails(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), kind TEXT NOT NULL CHECK(kind IN ('sale','quote')), document_id INTEGER NOT NULL, recipient TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS collections(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER NOT NULL REFERENCES customers(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, amount INTEGER NOT NULL, method TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', request_id TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS collection_allocations(id INTEGER PRIMARY KEY, collection_id INTEGER NOT NULL REFERENCES collections(id), receivable_id INTEGER NOT NULL REFERENCES receivables(id), sale_id INTEGER NOT NULL REFERENCES sales(id), amount INTEGER NOT NULL, balance_after INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_collections_customer_date ON collections(business_id,customer_id,created);
CREATE INDEX IF NOT EXISTS idx_collection_allocations_collection ON collection_allocations(collection_id);

-- Modulo de contabilidad y finanzas

CREATE TABLE IF NOT EXISTS finance_permissions(user_id INTEGER NOT NULL, business_id INTEGER NOT NULL, can_view INTEGER NOT NULL DEFAULT 0, can_write INTEGER NOT NULL DEFAULT 0, can_create INTEGER NOT NULL DEFAULT 0, can_edit INTEGER NOT NULL DEFAULT 0, can_authorize INTEGER NOT NULL DEFAULT 0, can_report INTEGER NOT NULL DEFAULT 0, can_export INTEGER NOT NULL DEFAULT 0, can_configure INTEGER NOT NULL DEFAULT 0, can_void INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,business_id));
INSERT OR IGNORE INTO finance_permissions(user_id,business_id,can_view,can_write,can_edit,can_authorize,can_report,can_configure,can_void) SELECT u.id,b.id,1,1,1,1,1,1,1 FROM users u CROSS JOIN businesses b WHERE u.role='admin';

CREATE TABLE IF NOT EXISTS finance_settings(business_id INTEGER PRIMARY KEY, distribution_pct INTEGER NOT NULL DEFAULT 3000, reinvestment_pct INTEGER NOT NULL DEFAULT 1700, updated_by INTEGER, updated_at TEXT);
INSERT OR IGNORE INTO finance_settings(business_id) SELECT id FROM businesses;
CREATE TABLE IF NOT EXISTS finance_accounts(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,opening_balance INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,shared_reference TEXT NOT NULL DEFAULT '',UNIQUE(business_id,name));
INSERT OR IGNORE INTO finance_accounts(id,business_id,name,type) VALUES(101,1,'Efectivo','cash'),(102,1,'Nequi','wallet'),(103,1,'Bancolombia','bank'),(104,1,'Caja menor','petty_cash'),(201,2,'Efectivo','cash'),(202,2,'Nequi','wallet'),(203,2,'Bancolombia','bank'),(204,2,'Caja menor','petty_cash');
CREATE TABLE IF NOT EXISTS finance_movements(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,created TEXT NOT NULL,effective_date TEXT NOT NULL,kind TEXT NOT NULL,concept TEXT NOT NULL,source_type TEXT,source_id INTEGER,direction INTEGER NOT NULL,amount INTEGER NOT NULL,balance_after INTEGER NOT NULL,user_id INTEGER NOT NULL,request_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',reversal_of INTEGER,UNIQUE(business_id,request_id));
CREATE INDEX IF NOT EXISTS idx_finance_movements_account ON finance_movements(business_id,account_id,effective_date,id);

CREATE TABLE IF NOT EXISTS finance_invoices(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,number TEXT NOT NULL,invoice_date TEXT NOT NULL,description TEXT NOT NULL,total INTEGER NOT NULL,tax INTEGER NOT NULL DEFAULT 0,supplier TEXT NOT NULL DEFAULT '',supplier_document TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT '',due_date TEXT,note TEXT NOT NULL DEFAULT '',attachment TEXT NOT NULL DEFAULT '',purchase_id INTEGER,status TEXT NOT NULL DEFAULT 'pending',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_invoice_payments(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,invoice_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));

CREATE TABLE IF NOT EXISTS finance_employees(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,document TEXT NOT NULL DEFAULT '',position TEXT NOT NULL DEFAULT '',salary INTEGER NOT NULL,started TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,usual_account_id INTEGER,note TEXT NOT NULL DEFAULT '',UNIQUE(business_id,document));
CREATE TABLE IF NOT EXISTS finance_payrolls(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,employee_id INTEGER NOT NULL,period TEXT NOT NULL,days_worked INTEGER NOT NULL,base_salary INTEGER NOT NULL,bonuses INTEGER NOT NULL DEFAULT 0,advances INTEGER NOT NULL DEFAULT 0,deductions INTEGER NOT NULL DEFAULT 0,net_total INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(business_id,employee_id,period));
CREATE TABLE IF NOT EXISTS finance_payroll_payments(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,payroll_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));

CREATE TABLE IF NOT EXISTS finance_profits(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,period TEXT NOT NULL,profit INTEGER NOT NULL,distribution_pct INTEGER NOT NULL,reinvestment_pct INTEGER NOT NULL,distribution_fund INTEGER NOT NULL,reinvestment INTEGER NOT NULL,available_distribution INTEGER NOT NULL,remaining_profit INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(business_id,period));
CREATE TABLE IF NOT EXISTS finance_beneficiaries(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,name TEXT NOT NULL,document TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS finance_profit_payouts(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,profit_id INTEGER NOT NULL,beneficiary_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,paid_at TEXT NOT NULL,user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_reinvestment_uses(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,used_at TEXT NOT NULL,concept TEXT NOT NULL,invoice_id INTEGER,note TEXT NOT NULL DEFAULT '',user_id INTEGER NOT NULL,movement_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',request_id TEXT NOT NULL,UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS finance_reconciliations(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,account_id INTEGER NOT NULL,observed INTEGER NOT NULL,book_balance INTEGER NOT NULL,difference INTEGER NOT NULL,reconciled_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',user_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS finance_profit_funding(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL,profit_id INTEGER NOT NULL,account_id INTEGER NOT NULL,amount INTEGER NOT NULL,movement_id INTEGER NOT NULL,UNIQUE(profit_id,account_id));

-- Recaudo de lácteos caseros por cuenta de terceros
CREATE TABLE IF NOT EXISTS dairy_products(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL,price INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO dairy_products(id,code,name,unit) VALUES(1,'LECHE','Leche de ordeño','litro'),(2,'QUESO','Queso campesino','libra');
CREATE TABLE IF NOT EXISTS dairy_permissions(user_id INTEGER PRIMARY KEY,can_view INTEGER NOT NULL DEFAULT 0,can_price INTEGER NOT NULL DEFAULT 0,can_void INTEGER NOT NULL DEFAULT 0,can_close INTEGER NOT NULL DEFAULT 0,can_reopen INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO dairy_permissions(user_id,can_view,can_price,can_void,can_close,can_reopen) SELECT id,1,1,1,1,1 FROM users WHERE role='admin';
CREATE TABLE IF NOT EXISTS dairy_sale_lines(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL,product_id INTEGER NOT NULL,qty INTEGER NOT NULL,price INTEGER NOT NULL,total INTEGER NOT NULL,created TEXT NOT NULL,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE INDEX IF NOT EXISTS idx_dairy_sales_date ON dairy_sale_lines(created,status);
CREATE TABLE IF NOT EXISTS dairy_payments(id INTEGER PRIMARY KEY,sale_id INTEGER NOT NULL,method TEXT NOT NULL,amount INTEGER NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dairy_returns(id INTEGER PRIMARY KEY,line_id INTEGER NOT NULL,qty INTEGER NOT NULL,amount INTEGER NOT NULL,created TEXT NOT NULL,user_id INTEGER NOT NULL,reason TEXT NOT NULL,request_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS dairy_closures(id INTEGER PRIMARY KEY,day TEXT UNIQUE NOT NULL,expected INTEGER NOT NULL,counted INTEGER NOT NULL,difference INTEGER NOT NULL,closed_at TEXT NOT NULL,closed_by INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'closed',reopened_at TEXT,reopened_by INTEGER,reopen_reason TEXT NOT NULL DEFAULT '');

-- Despachos y formatos de etiquetas
CREATE TABLE IF NOT EXISTS dispatches(id INTEGER PRIMARY KEY,business_id INTEGER NOT NULL REFERENCES businesses(id),number INTEGER NOT NULL,sale_id INTEGER NOT NULL REFERENCES sales(id),created TEXT NOT NULL,scheduled_date TEXT NOT NULL,scheduled_time TEXT NOT NULL DEFAULT '',contact_phone TEXT NOT NULL DEFAULT '',recipient_name TEXT NOT NULL DEFAULT '',recipient_phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',neighborhood TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',department TEXT NOT NULL DEFAULT '',reference_point TEXT NOT NULL DEFAULT '',address_note TEXT NOT NULL DEFAULT '',instructions TEXT NOT NULL DEFAULT '',responsible TEXT NOT NULL DEFAULT '',driver TEXT NOT NULL DEFAULT '',vehicle_plate TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Pendiente',delivered_at TEXT,received_by TEXT NOT NULL DEFAULT '',delivery_note TEXT NOT NULL DEFAULT '',confirmed_by INTEGER REFERENCES users(id),created_by INTEGER NOT NULL REFERENCES users(id),request_id TEXT NOT NULL,UNIQUE(business_id,number),UNIQUE(business_id,request_id));
CREATE INDEX IF NOT EXISTS idx_dispatches_business_date ON dispatches(business_id,created);
CREATE TABLE IF NOT EXISTS dispatch_lines(id INTEGER PRIMARY KEY,dispatch_id INTEGER NOT NULL REFERENCES dispatches(id),sale_line_id INTEGER NOT NULL REFERENCES sale_lines(id),product_id INTEGER NOT NULL REFERENCES products(id),name TEXT NOT NULL,sku TEXT NOT NULL,unit TEXT NOT NULL,qty INTEGER NOT NULL,delivered_qty INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS dispatch_history(id INTEGER PRIMARY KEY,dispatch_id INTEGER NOT NULL REFERENCES dispatches(id),created TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),from_status TEXT NOT NULL DEFAULT '',to_status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS label_settings(business_id INTEGER PRIMARY KEY REFERENCES businesses(id),format TEXT NOT NULL DEFAULT 'large',width_mm INTEGER NOT NULL DEFAULT 72,height_mm INTEGER NOT NULL DEFAULT 45,margin_mm INTEGER NOT NULL DEFAULT 2,name_size INTEGER NOT NULL DEFAULT 12,price_size INTEGER NOT NULL DEFAULT 22,barcode_height INTEGER NOT NULL DEFAULT 18,gap_mm INTEGER NOT NULL DEFAULT 2,updated_by INTEGER REFERENCES users(id),updated_at TEXT);
INSERT OR IGNORE INTO label_settings(business_id) SELECT id FROM businesses;
